<?php
/** Unified human Approval Center. @package AIContentStudio */
if(!defined('ABSPATH')){exit;}
final class AICS_Approvals_Page{
	private const SLUG='aics-approvals';
	public static function register():void{foreach(array('approve_idea','reject_idea','approve_article','reject_article') as $action){add_action('admin_post_aics_'.$action,array(__CLASS__,'handle_'.$action));}}
	public static function render():void{self::permission();$ideas=new AICS_Content_Idea_Repository();$articles=new AICS_Article_Repository();$idea_count=$ideas->count_ideas(array('status'=>'pending_approval'));$article_count=$articles->count_articles(array('status'=>'pending_approval'));$type=isset($_GET['approval_type'])?sanitize_key(wp_unslash($_GET['approval_type'])):'';if(!in_array($type,array('ideas','articles'),true)){$type=$idea_count>0?'ideas':($article_count>0?'articles':'ideas');}$view=isset($_GET['view'])?sanitize_key(wp_unslash($_GET['view'])):'';$notice=isset($_GET['aics_notice'])?sanitize_key(wp_unslash($_GET['aics_notice'])):'';?>
	<div class="wrap aics-admin-wrap aics-approvals-page"><header class="aics-page-header"><h1><?php esc_html_e('Approvals','ai-content-studio');?></h1><p class="aics-page-description"><?php esc_html_e('Review pending automation ideas and generated articles. Decisions resume the existing background workflow without generating content or creating WordPress posts.','ai-content-studio');?></p></header><?php self::notice($notice);?><div class="aics-summary-grid"><div class="aics-dashboard-card"><span><?php esc_html_e('Ideas Awaiting Approval','ai-content-studio');?></span><strong><?php echo esc_html(number_format_i18n($idea_count));?></strong></div><div class="aics-dashboard-card"><span><?php esc_html_e('Articles Awaiting Approval','ai-content-studio');?></span><strong><?php echo esc_html(number_format_i18n($article_count));?></strong></div></div><nav class="aics-approval-tabs" aria-label="<?php esc_attr_e('Approval types','ai-content-studio');?>"><a class="<?php echo 'ideas'===$type?'current':'';?>" <?php echo 'ideas'===$type?'aria-current="page"':'';?> href="<?php echo esc_url(self::url('ideas'));?>"><?php esc_html_e('Ideas','ai-content-studio');?> (<?php echo esc_html($idea_count);?>)</a><a class="<?php echo 'articles'===$type?'current':'';?>" <?php echo 'articles'===$type?'aria-current="page"':'';?> href="<?php echo esc_url(self::url('articles'));?>"><?php esc_html_e('Articles','ai-content-studio');?> (<?php echo esc_html($article_count);?>)</a></nav>
	<?php if('review'===$view){'ideas'===$type?self::review_idea($ideas):self::review_article($articles,$ideas);}else{'ideas'===$type?self::list_ideas($ideas,$idea_count):self::list_articles($articles,$article_count);}?></div><?php }
	private static function list_ideas(AICS_Content_Idea_Repository $repo,int $total):void{$page=max(1,absint($_GET['paged']??1));$items=$repo->get_ideas(array('status'=>'pending_approval','limit'=>20,'offset'=>($page-1)*20,'orderby'=>'created_at','order'=>'ASC'));if(!$items){self::empty_state(__('No ideas are awaiting approval.','ai-content-studio'));return;}?><div class="aics-table-wrap"><table class="widefat striped aics-approval-table"><thead><tr><th><?php esc_html_e('Idea','ai-content-studio');?></th><th><?php esc_html_e('Score','ai-content-studio');?></th><th><?php esc_html_e('Primary Keyword','ai-content-studio');?></th><th><?php esc_html_e('Search Intent','ai-content-studio');?></th><th><?php esc_html_e('Automation Profile','ai-content-studio');?></th><th><?php esc_html_e('Created','ai-content-studio');?></th><th><?php esc_html_e('Action','ai-content-studio');?></th></tr></thead><tbody><?php foreach($items as $i):$p=(new AICS_Automation_Profile_Repository())->get_by_id($i['profile_id']);?><tr><td><strong><?php echo esc_html($i['title']);?></strong><br><span><?php echo esc_html(wp_html_excerpt($i['summary'],120,'…'));?></span></td><td><?php echo esc_html(number_format_i18n($i['score'],2));?></td><td><?php echo esc_html($i['primary_keyword']);?></td><td><?php echo esc_html(ucwords(str_replace('_',' ',$i['search_intent'])));?></td><td><?php echo esc_html($p['profile_name']??__('Unavailable','ai-content-studio'));?></td><td><?php echo esc_html(self::date($i['created_at']));?></td><td><a class="button" href="<?php echo esc_url(add_query_arg(array('page'=>self::SLUG,'approval_type'=>'ideas','view'=>'review','idea_id'=>$i['id']),admin_url('admin.php')));?>"><?php esc_html_e('Review','ai-content-studio');?></a></td></tr><?php endforeach;?></tbody></table></div><?php self::pagination($total,$page,'ideas');}
	private static function list_articles(AICS_Article_Repository $repo,int $total):void{$page=max(1,absint($_GET['paged']??1));$items=$repo->get_articles(array('status'=>'pending_approval','limit'=>20,'offset'=>($page-1)*20,'orderby'=>'generated_at','order'=>'ASC'));if(!$items){self::empty_state(__('No articles are awaiting approval.','ai-content-studio'));return;}?><div class="aics-table-wrap"><table class="widefat striped aics-approval-table"><thead><tr><th><?php esc_html_e('Article','ai-content-studio');?></th><th><?php esc_html_e('Word Count','ai-content-studio');?></th><th><?php esc_html_e('Automation Profile','ai-content-studio');?></th><th><?php esc_html_e('Generated','ai-content-studio');?></th><th><?php esc_html_e('Planned Publishing Time','ai-content-studio');?></th><th><?php esc_html_e('Action','ai-content-studio');?></th></tr></thead><tbody><?php foreach($items as $a):$p=(new AICS_Automation_Profile_Repository())->get_by_id($a['profile_id']);?><tr><td><strong><?php echo esc_html($a['title']);?></strong><br><span><?php echo esc_html(wp_html_excerpt($a['excerpt'],140,'…'));?></span></td><td><?php echo esc_html(number_format_i18n($a['word_count']));?></td><td><?php echo esc_html($p['profile_name']??__('Unavailable','ai-content-studio'));?></td><td><?php echo esc_html(self::date($a['generated_at']));?></td><td><?php echo esc_html(self::date($a['planned_publish_at']));?></td><td><a class="button" href="<?php echo esc_url(add_query_arg(array('page'=>self::SLUG,'approval_type'=>'articles','view'=>'review','article_id'=>$a['id']),admin_url('admin.php')));?>"><?php esc_html_e('Review','ai-content-studio');?></a></td></tr><?php endforeach;?></tbody></table></div><?php self::pagination($total,$page,'articles');}
	private static function review_idea(AICS_Content_Idea_Repository $repo):void{$id=absint($_GET['idea_id']??0);$i=$repo->get_by_id($id);if(!$i){self::empty_state(__('The selected approval item no longer exists.','ai-content-studio'));return;}$p=(new AICS_Automation_Profile_Repository())->get_by_id($i['profile_id']);?><section class="aics-card aics-approval-review"><div class="aics-card-header"><h2><?php echo esc_html($i['title']);?></h2></div><div class="aics-card-body"><p><span class="aics-status-badge"><?php echo esc_html(ucwords(str_replace('_',' ',$i['status'])));?></span></p><dl class="aics-review-details"><div><dt><?php esc_html_e('Summary','ai-content-studio');?></dt><dd><?php echo esc_html($i['summary']);?></dd></div><div><dt><?php esc_html_e('Primary keyword','ai-content-studio');?></dt><dd><?php echo esc_html($i['primary_keyword']);?></dd></div><div><dt><?php esc_html_e('Secondary keywords','ai-content-studio');?></dt><dd><?php self::text_list($i['secondary_keywords']);?></dd></div><div><dt><?php esc_html_e('Search intent','ai-content-studio');?></dt><dd><?php echo esc_html($i['search_intent']);?></dd></div><div><dt><?php esc_html_e('Suggested category','ai-content-studio');?></dt><dd><?php echo esc_html($i['suggested_category']);?></dd></div><div><dt><?php esc_html_e('Score','ai-content-studio');?></dt><dd><?php echo esc_html(number_format_i18n($i['score'],2));?></dd></div><div><dt><?php esc_html_e('Automation profile','ai-content-studio');?></dt><dd><?php echo esc_html($p['profile_name']??__('Unavailable','ai-content-studio'));?></dd></div><div><dt><?php esc_html_e('Generated','ai-content-studio');?></dt><dd><?php echo esc_html(self::date($i['created_at']));?></dd></div><div><dt><?php esc_html_e('Outline','ai-content-studio');?></dt><dd><?php self::text_list($i['outline']);?></dd></div></dl><?php if('pending_approval'===$i['status']){self::decision_forms('idea',$id);}else{?><div class="notice notice-info inline"><p><?php esc_html_e('This idea has already been processed. Active decision controls are no longer available.','ai-content-studio');?></p></div><?php }?><p><a href="<?php echo esc_url(self::url('ideas'));?>"><?php esc_html_e('Back to Approvals','ai-content-studio');?></a></p></div></section><?php }
	private static function review_article(AICS_Article_Repository $repo,AICS_Content_Idea_Repository $ideas):void{$id=absint($_GET['article_id']??0);$a=$repo->get_by_id($id);if(!$a){self::empty_state(__('The selected approval item no longer exists.','ai-content-studio'));return;}$i=$ideas->get_by_id($a['idea_id']);$p=(new AICS_Automation_Profile_Repository())->get_by_id($a['profile_id']);?><section class="aics-card aics-approval-review"><div class="aics-card-header"><h2><?php echo esc_html($a['title']);?></h2></div><div class="aics-card-body"><p><span class="aics-status-badge"><?php echo esc_html(ucwords(str_replace('_',' ',$a['status'])));?></span></p><dl class="aics-review-details"><div><dt><?php esc_html_e('Excerpt','ai-content-studio');?></dt><dd><?php echo esc_html($a['excerpt']);?></dd></div><div><dt><?php esc_html_e('Word count','ai-content-studio');?></dt><dd><?php echo esc_html(number_format_i18n($a['word_count']));?></dd></div><div><dt><?php esc_html_e('Related idea','ai-content-studio');?></dt><dd><?php echo esc_html($i['title']??__('Unavailable','ai-content-studio'));?></dd></div><div><dt><?php esc_html_e('Automation profile','ai-content-studio');?></dt><dd><?php echo esc_html($p['profile_name']??__('Unavailable','ai-content-studio'));?></dd></div><div><dt><?php esc_html_e('Generated','ai-content-studio');?></dt><dd><?php echo esc_html(self::date($a['generated_at']));?></dd></div><div><dt><?php esc_html_e('Planned publication','ai-content-studio');?></dt><dd><?php echo esc_html(self::date($a['planned_publish_at']));?></dd></div></dl><div class="aics-article-preview" aria-label="<?php esc_attr_e('Read-only article preview','ai-content-studio');?>"><?php echo wp_kses_post($a['content']);?></div><?php if('pending_approval'===$a['status']){self::decision_forms('article',$id);}else{?><div class="notice notice-info inline"><p><?php esc_html_e('This article has already been processed. Active decision controls are no longer available.','ai-content-studio');?></p></div><?php }?><p><a href="<?php echo esc_url(self::url('articles'));?>"><?php esc_html_e('Back to Approvals','ai-content-studio');?></a></p></div></section><?php }
	private static function decision_forms(string $type,int $id):void{$is_idea='idea'===$type;$reasons=$is_idea?array('off_topic'=>__('Not relevant to the business','ai-content-studio'),'duplicate_concept'=>__('Too similar to another topic','ai-content-studio'),'low_business_value'=>__('Low value for the content plan','ai-content-studio'),'not_for_target_audience'=>__('Not suitable for the target audience','ai-content-studio'),'not_suitable'=>__('Not suitable for this cycle','ai-content-studio')):array('needs_revision'=>__('Needs substantial revision','ai-content-studio'),'off_brand'=>__('Does not match the brand voice','ai-content-studio'),'fact_check_required'=>__('Requires factual review','ai-content-studio'),'quality_issue'=>__('Content quality is not acceptable','ai-content-studio'),'not_suitable'=>__('Not suitable for publishing','ai-content-studio'));?><div class="aics-decision-grid"><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="aics_approve_<?php echo esc_attr($type);?>"><input type="hidden" name="<?php echo esc_attr($type);?>_id" value="<?php echo esc_attr($id);?>"><?php wp_nonce_field('aics_approve_'.$type.'_'.$id);?><button class="button button-primary" type="submit"><?php echo esc_html($is_idea?__('Approve Idea','ai-content-studio'):__('Approve Article','ai-content-studio'));?></button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="aics_reject_<?php echo esc_attr($type);?>"><input type="hidden" name="<?php echo esc_attr($type);?>_id" value="<?php echo esc_attr($id);?>"><?php wp_nonce_field('aics_reject_'.$type.'_'.$id);?><label for="aics-reason-<?php echo esc_attr($type);?>-<?php echo esc_attr($id);?>"><?php esc_html_e('Rejection reason','ai-content-studio');?></label><select required id="aics-reason-<?php echo esc_attr($type);?>-<?php echo esc_attr($id);?>" name="rejection_code"><option value=""><?php esc_html_e('Select a reason','ai-content-studio');?></option><?php foreach($reasons as $code=>$label):?><option value="<?php echo esc_attr($code);?>"><?php echo esc_html($label);?></option><?php endforeach;?></select><button class="button aics-button-danger" type="submit"><?php echo esc_html($is_idea?__('Reject Idea','ai-content-studio'):__('Reject Article','ai-content-studio'));?></button></form></div><?php }
	public static function handle_approve_idea():void{self::handle('idea','approve');}public static function handle_reject_idea():void{self::handle('idea','reject');}public static function handle_approve_article():void{self::handle('article','approve');}public static function handle_reject_article():void{self::handle('article','reject');}
	private static function handle(string $type,string $decision):void{self::permission();if('POST'!==($_SERVER['REQUEST_METHOD']??'')){self::redirect($type.'s','request_not_verified');}$id=absint($_POST[$type.'_id']??0);$nonce=isset($_POST['_wpnonce'])?sanitize_text_field(wp_unslash($_POST['_wpnonce'])):'';if(!$id||!wp_verify_nonce($nonce,'aics_'.$decision.'_'.$type.'_'.$id)){self::redirect($type.'s','request_not_verified');}$service=new AICS_Approval_Workflow_Service();$method=$decision.'_'.$type;$result='reject'===$decision?$service->$method($id,get_current_user_id(),sanitize_key(wp_unslash($_POST['rejection_code']??''))):$service->$method($id,get_current_user_id());$notice=$result['code'];if($result['success']&&in_array($result['run_code']??'',array('run_resumed','all_ideas_rejected','all_articles_rejected'),true)){$notice='run_resumed'===$result['run_code']?($type.'_run_resumed'):$result['run_code'];}self::redirect($type.'s',$notice);}
	private static function redirect(string $type,string $notice):void{wp_safe_redirect(add_query_arg(array('page'=>self::SLUG,'approval_type'=>$type,'aics_notice'=>sanitize_key($notice)),admin_url('admin.php')));exit;}
	private static function permission():void{if(!is_user_logged_in()||!current_user_can(\AIContentStudio\Core\Permissions::manage())){wp_die(esc_html__('You are not allowed to manage approvals.','ai-content-studio'));}}
	private static function notice(string $code):void{$map=array('idea_approved'=>array('success',__('Idea approved and queued for article generation.','ai-content-studio')),'idea_rejected'=>array('success',__('Idea rejected.','ai-content-studio')),'idea_run_resumed'=>array('success',__('Idea decisions are complete and automation will continue.','ai-content-studio')),'article_approved'=>array('success',__('Article approved.','ai-content-studio')),'article_rejected'=>array('success',__('Article rejected.','ai-content-studio')),'article_run_resumed'=>array('success',__('Article decisions are complete. WordPress post creation is the next workflow step.','ai-content-studio')),'all_ideas_rejected'=>array('warning',__('All ideas were rejected and the automation run has stopped.','ai-content-studio')),'all_articles_rejected'=>array('warning',__('All articles were rejected and the automation run has stopped.','ai-content-studio')),'idea_approval_limit_reached'=>array('warning',__('The configured idea approval limit has been reached. Reject the remaining ideas to continue.','ai-content-studio')),'idea_already_approved'=>array('info',__('This idea has already been processed.','ai-content-studio')),'article_already_approved'=>array('info',__('This article has already been processed.','ai-content-studio')),'approval_item_missing'=>array('error',__('The selected approval item no longer exists.','ai-content-studio')),'idea_decision_conflict'=>array('error',__('The approval decision conflicts with the current idea status.','ai-content-studio')),'article_decision_conflict'=>array('error',__('The approval decision conflicts with the current article status.','ai-content-studio')),'invalid_rejection_reason'=>array('error',__('Select a valid controlled rejection reason.','ai-content-studio')),'request_not_verified'=>array('error',__('The approval request could not be verified.','ai-content-studio')));if(isset($map[$code])){echo '<div class="notice notice-'.esc_attr($map[$code][0]).'"><p>'.esc_html($map[$code][1]).'</p></div>';}}
	private static function pagination(int $total,int $page,string $type):void{$pages=(int)ceil($total/20);if($pages<2){return;}echo '<div class="tablenav"><div class="tablenav-pages">'.wp_kses_post(paginate_links(array('base'=>add_query_arg(array('page'=>self::SLUG,'approval_type'=>$type,'paged'=>'%#%'),admin_url('admin.php')),'current'=>$page,'total'=>$pages))).'</div></div>';}
	private static function url(string $type):string{return add_query_arg(array('page'=>self::SLUG,'approval_type'=>$type),admin_url('admin.php'));}private static function date($date):string{return $date?get_date_from_gmt($date,get_option('date_format').' '.get_option('time_format')):__('Not set','ai-content-studio');}private static function text_list(array $items):void{if(!$items){echo esc_html__('None','ai-content-studio');return;}echo '<ul>';foreach($items as $item){echo '<li>'.esc_html($item).'</li>';}echo '</ul>';}private static function empty_state(string $message):void{echo '<div class="aics-empty-state"><h2>'.esc_html__('Nothing awaiting review','ai-content-studio').'</h2><p>'.esc_html($message).'</p></div>';}
}
